package com.teslacharge.xp3.data;

public final class GraphqlQueries {
    private GraphqlQueries() {}
    public static final String GET_ACTIVE_CHARGING_SESSIONS = "\nquery GetActiveChargingSessions($vin: String) {\n  charging {\n    activeSessions(vin: $vin) {\n      authorizationSessionId\n      siteId\n      postId\n      sessionEvents\n      createdTimeEpoch { ...GoogleProtoTimeStampFragment }\n      lastUpdatedTimeEpoch { ...GoogleProtoTimeStampFragment }\n      chargeEndTimeEpoch { ...GoogleProtoTimeStampFragment }\n      isDcEnforced\n      showMetrology\n      isWcCtepEnforced\n      trtId { value }\n      locationGUID\n      programType\n    }\n  }\n}\n\nfragment GoogleProtoTimeStampFragment on GoogleProtoTimeStamp {\n  nanos\n  seconds\n}";
    public static final String GET_CHARGING_HISTORY = "\nquery getChargingHistoryV2($vin: String, $sortBy: String, $sortOrder: SortByEnum, $pageNumber: Int, $startTime: DateISO, $endTime: DateISO) {\n  me {\n    charging {\n      historyV2(vin: $vin, sortBy: $sortBy, sortOrder: $sortOrder, pageNumber: $pageNumber, startTime: $startTime, endTime: $endTime) {\n        data {\n          chargeSessionId\n          countryCode\n          vin\n          sessionId\n          chargeStartDateTime\n          chargeStopDateTime\n          unlatchDateTime\n          siteLocationName\n          programType\n          siteEntryLocation {\n            latitude\n            longitude\n          }\n          siteAddress {\n            street\n            streetNumber\n            city\n            state\n            postalCode\n            countryCode\n            country\n          }\n          fees {\n            currencyCode\n            feeType\n            isPaid\n            pricingType\n            rateBase\n            rateTier1\n            rateTier2\n            status\n            totalBase\n            totalDue\n            totalTier1\n            totalTier2\n            uom\n            usageBase\n            usageTier1\n            usageTier2\n          }\n        }\n        totalResults\n        hasMoreData\n      }\n    }\n  }\n}";
    public static final String GET_CHARGING_SESSION_BY_ID = "\nquery GetChargingSessionById($authorizationSessionId: String!) {\n  charging {\n    sessionInfo(authorizationSessionId: $authorizationSessionId) {\n      authorizationSessionId\n      cumulativeEnergy\n      hasCumulativeEnergy\n      cumulativeCost\n      currency\n      sessionEvents\n      authorizationEndReason\n      chargeEndTimeEpoch { ...GoogleProtoTimeStampFragment }\n      chargeStartTimeEpoch { ...GoogleProtoTimeStampFragment }\n      instantaneousPowerW { value }\n      voltageV { value }\n      currentA { value }\n      currentServerTime\n      stateOfCharge { value }\n      timeToFull { ...GoogleProtoDurationFragment }\n      timeToBulk { ...GoogleProtoDurationFragment }\n    }\n  }\n}\n\nfragment GoogleProtoTimeStampFragment on GoogleProtoTimeStamp {\n  nanos\n  seconds\n}\n\nfragment GoogleProtoDurationFragment on GoogleProtoDuration {\n  nanos\n  seconds\n}";
    public static final String GET_CHARGING_SESSION_SUMMARY = "\nquery GetChargingSessionSummary($authorizationSessionId: String!) {\n  charging {\n    sessionSummary(authorizationSessionId: $authorizationSessionId) {\n      chargeSessionId\n      chargeStartDateTime\n      chargeStopDateTime\n      unlatchDateTime\n      countryCode\n      siteLocationName\n      isMsp\n      programType\n      fees {\n        currencyCode\n        feeType\n        isPaid\n        pricingType\n        rateBase\n        rateTier1\n        rateTier2\n        status\n        totalBase\n        totalDue\n        totalTier1\n        totalTier2\n        uom\n        usageBase\n        usageTier1\n        usageTier2\n      }\n    }\n  }\n}";
    public static final String GET_NON_TESLA_EVS = "\nquery getNonTeslaEvs {\n  me {\n    nonTeslaEvs {\n      evUuid\n      hasNacsAdapter\n      make\n      makeLabel\n      maxRange\n      maxRangeUnit\n      model\n      year\n      licensePlate\n    }\n  }\n}";
    public static final String GET_PAYMENT_INSTRUMENT = "\nquery GetInstrumentBySource($paymentSource: PaymentGatewayPaymentSourceEnum!, $countryCode: String, $currencyCode: String, $sourceFlow: PaymentSourceFlowEnum) {\n  me {\n    payment {\n      getInstrumentBySource(paymentSource: $paymentSource, countryCode: $countryCode, currencyCode: $currencyCode, sourceFlow: $sourceFlow) {\n        expiryMonth\n        expiryYear\n        lastFourDigits\n        paymentChannels\n        paymentInstrumentType\n        accountType\n      }\n    }\n  }\n}";
    public static final String GET_PENDING_BALANCES = "\nquery getPendingBalances {\n  me {\n    charging {\n      balances {\n        ntslaInvolved\n        list { amount countryCode currencyCode sessionFeeIds }\n      }\n    }\n  }\n}";
    public static final String GET_SITE_BY_ID = "\nquery getSiteById($siteId: SiteIdInput!, $vehicleMakeType: VehicleMakeType!) {\n  chargingNetwork {\n    site(siteId: $siteId) {\n      __typename\n      ...SiteBaseFragment\n      nacsOnlyAssets {\n        banner { header caption link }\n        disclaimer { text sheetTitle sheetContent }\n      }\n      disclaimers { text type }\n      chargerList { ...ChargerFragment }\n      isCanvasSite\n      currentCongestion\n      holdAmount(vehicleMakeType: $vehicleMakeType) { ...ChargingPriceFragment }\n      pricing(vehicleMakeType: $vehicleMakeType) { ...SitePricingFragment }\n      vehicleSelection { required }\n      ownershipType\n      convenienceFeatures\n      accessControl {\n        hasAccess\n        statusMessage { status message header }\n      }\n    }\n  }\n}\n\nfragment SiteBaseFragment on SiteBase {\n  ... on SiteBase {\n    name\n    address { ...AddressFragment }\n    centroid { ...LatLngFragment }\n    entryPoint { ...LatLngFragment }\n    openToPublic\n    amenities\n    accessCode\n    activeOutageMessage\n    maxPowerKw\n    timeZone\n    locationGUID\n    trtId\n    powerType\n    accessType\n    openToNonTeslas\n    waitEstimateBucket\n    siteUsabilityArchetype\n    hasMagicDockAdapter\n    chargingAccessibility\n    displayName\n    displaySubTitle\n    localizedSiteName\n    isMagicDockSupportedSite\n    isMagicDockSupportedV2Site\n    haversineDistanceMiles\n    availableStalls\n    totalStalls\n    siteType\n    hasHighCongestion\n    openHour { hour openNow shouldDisplay }\n    additionalNavInstructions\n    teslaExclusive\n    siteCapabilities\n    owner\n    operator\n    payToPark\n    payToParkInstructions\n    parkingLevel\n    parkingLevelType\n    valetOnly\n    noRestrooms\n    accessRestriction\n    accessInstruction\n    criticalInfo\n  }\n}\n\nfragment AddressFragment on Address {\n  street\n  streetNumber\n  city\n  district\n  state\n  countryCode\n  country\n  postalCode\n}\n\nfragment LatLngFragment on LatLng {\n  latitude\n  longitude\n}\nfragment ChargerFragment on Charger {\n  id\n  label\n  availability\n  powerKw\n  standard\n  connectorId\n}\n\nfragment ChargingPriceFragment on ChargingPrice {\n  currencyCode\n  price\n}\n\nfragment SitePricingFragment on SitePricing {\n  userRates { ...ChargingActiveRateFragment }\n  memberRates { ...ChargingActiveRateFragment }\n  hasMembershipPricing\n  hasMSPPricing\n  pricingDisclaimers { type title description }\n  canDisplayCombinedComparison\n  histogram { ...SitePricingHistogramFragment }\n}\n\nfragment ChargingActiveRateFragment on ChargingActiveRate {\n  activePricebook { ...ActivePricebookFragment }\n  pricebooksForConnectors {\n    connectorIds\n    pricebook { ...ActivePricebookFragment }\n  }\n}\n\nfragment ActivePricebookFragment on ChargingPricebook {\n  charging {\n    dynamicRates { enabled level ratesByOccupancy { min max rates } }\n    ...ChargingUserRateFragment\n  }\n  parking { ...ChargingUserRateFragment }\n  congestion { ...ChargingUserRateFragment }\n  service { ...ChargingUserRateFragment }\n  electricity { ...ChargingUserRateFragment }\n  flat { ...ChargingUserRateFragment }\n  duration { ...ChargingUserRateFragment }\n  priceBookID\n}\n\nfragment ChargingUserRateFragment on ChargingUserRate {\n  currencyCode\n  currencyComparisons { toCurrency exchangeRate }\n  programType\n  rates\n  buckets { start end }\n  bucketUom\n  touRates {\n    enabled\n    activeRatesByTime { startTime endTime rates }\n  }\n  uom\n  vehicleMakeType\n  stateOfCharge\n  congestionGracePeriodSecs\n  congestionPercent\n}\n\nfragment SitePricingHistogramFragment on SitePricingHistogram {\n  axisLabels { index value }\n  regionLabels { index value { ...ChargingPriceFragment } }\n  chargingUom\n  parkingUom\n  parkingRate { ...ChargingPriceFragment }\n  data { value congestionThreshold label }\n  activeBar\n  maxRateIndex\n  whenRateChanges\n}";
    public static final String GET_SITE_LIST = "\nquery getSiteList($siteFilter: SiteFilterInput!, $vehicleMakeType: VehicleMakeType!) {\n  chargingNetwork {\n    siteList(siteFilter: $siteFilter) {\n      __typename\n      ...SiteBaseFragment\n      ... on MapSiteROW {\n        isThirdPartySite\n        isCanvasSite\n        ownershipType\n        pricing(vehicleMakeType: $vehicleMakeType) {\n          userRates {\n            activePricebook {\n              charging {\n                currencyCode\n                currencyComparisons { toCurrency exchangeRate }\n                rates\n                dynamicRates { enabled level }\n                uom\n              }\n            }\n          }\n        }\n      }\n    }\n  }\n}\n\nfragment SiteBaseFragment on SiteBase {\n  ... on SiteBase {\n    name\n    address { ...AddressFragment }\n    centroid { ...LatLngFragment }\n    entryPoint { ...LatLngFragment }\n    openToPublic\n    amenities\n    accessCode\n    activeOutageMessage\n    maxPowerKw\n    timeZone\n    locationGUID\n    trtId\n    powerType\n    accessType\n    openToNonTeslas\n    waitEstimateBucket\n    siteUsabilityArchetype\n    hasMagicDockAdapter\n    chargingAccessibility\n    displayName\n    displaySubTitle\n    localizedSiteName\n    isMagicDockSupportedSite\n    isMagicDockSupportedV2Site\n    haversineDistanceMiles\n    availableStalls\n    totalStalls\n    siteType\n    hasHighCongestion\n    openHour { hour openNow shouldDisplay }\n    additionalNavInstructions\n    teslaExclusive\n    siteCapabilities\n    owner\n    operator\n    payToPark\n    payToParkInstructions\n    parkingLevel\n    parkingLevelType\n    valetOnly\n    noRestrooms\n    accessRestriction\n    accessInstruction\n    criticalInfo\n  }\n}\n\nfragment AddressFragment on Address {\n  street\n  streetNumber\n  city\n  district\n  state\n  countryCode\n  country\n  postalCode\n}\n\nfragment LatLngFragment on LatLng {\n  latitude\n  longitude\n}";
    public static final String PRE_START_CHARGING_VALIDATION = "\nquery preStartChargingValidation($trtId: Int!, $programType: EPSChargingProgramType!, $deviceLanguage: String!, $deviceCountry: String!) {\n  me {\n    charging {\n      canStartCharging(\n        trtId: $trtId\n        programType: $programType\n        deviceCountry: $deviceCountry\n        deviceLanguage: $deviceLanguage\n      ) {\n        enabled\n        errors\n      }\n    }\n  }\n}";
    public static final String START_CHARGING_SESSION = "\nmutation StartChargingSession($postId: String!, $programType: ChargingProgramType!, $pricebookId: Int!, $deviceCountry: String, $deviceLanguage: String, $vehicleId: String, $occupiedChargers: Int, $totalChargers: Int, $source: ChargingSessionSourceEnum) {\n  charging {\n    startSession(\n      postId: $postId\n      pricebookId: $pricebookId\n      programType: $programType\n      deviceCountry: $deviceCountry\n      deviceLanguage: $deviceLanguage\n      vehicleId: $vehicleId\n      occupiedChargers: $occupiedChargers\n      totalChargers: $totalChargers\n      source: $source\n    ) {\n      authorizationSessionId\n      sessionEvents\n      startMessages\n      reason\n    }\n  }\n}";
    public static final String STOP_CHARGING_SESSION = "\nmutation StopChargingSessionById($authorizationSessionId: String!) {\n  charging {\n    stopSession(authorizationSessionId: $authorizationSessionId) {\n      isRequestDelivered\n    }\n  }\n}";
}
